#define BUF_SZ 256
char target[BUF_SZ];
const char *link_path = "/proc/self/exe";
ssize_t len;

// Function signature: ssize_t readlink(path, buf, bufsiz)
len = readlink(link_path, target, BUF_SZ);

if (len == -1) {
    /* Handle error (e.g., ENOENT, EINVAL) */
    return;
}

// Result is NOT null-terminated; len is the exact size written
if ((size_t)len < BUF_SZ) {
    target[len] = '\0'; // Manual termination
} else {
    /* Link target was truncated */
}

